package app.dayflow.markdown;final class Network {static String endpoint(String raw,boolean local)throws Exception{java.net.URI uri=new java.net.URI(raw);String host=uri.getHost();boolean lan=host!=null&&(host.equals("localhost")||host.equals("127.0.0.1")||host.startsWith("10.")||host.startsWith("192.168.")||host.matches("172\\.(1[6-9]|2[0-9]|3[01])\\..*"));if(uri.getRawUserInfo()!=null||!("https".equals(uri.getScheme())||local&&lan&&"http".equals(uri.getScheme())))throw new java.io.IOException("网络图片使用HTTPS，本地地址可用HTTP");return raw;}}
